24	    makeLabelFormatter,
25	    getOptionCategoryInterval,
26	    shouldShowAllLabels
27	} from './axisHelper';
28	import Axis from './Axis';
29	import Model from '../model/Model';
30	import { AxisBaseOption, CategoryAxisBaseOption } from './axisCommonTypes';
31	import OrdinalScale from '../scale/Ordinal';
32	import { AxisBaseModel } from './AxisBaseModel';
