110	
111	function tickValuesToNumbers(axis: Axis, values: (number | string | Date)[]) {
112	    const nums = zrUtil.map(values, val => axis.scale.parse(val));
113	    if (axis.type === 'time' && nums.length > 0) {
114	        // Time axis needs duplicate first/last tick (see TimeScale.getTicks())
115	        // The first and last tick/label don't get drawn
116	        nums.sort();
117	        nums.unshift(nums[0]);
118	        nums.push(nums[nums.length - 1]);
119	    }
120	    return nums;
121	}
122	
123	export function createAxisLabels(axis: Axis, ctx: AxisLabelsComputingContext): {
124	    labels: AxisLabelInfoDetermined[]
125	} {
126	    const custom = axis.getLabelModel().get('customValues');
127	    if (custom) {
128	        const labelFormatter = makeLabelFormatter(axis);
129	        const extent = axis.scale.getExtent();
130	        const tickNumbers = tickValuesToNumbers(axis, custom);
131	        const ticks = zrUtil.filter(tickNumbers, val => val >= extent[0] && val <= extent[1]);
132	        return {
133	            labels: zrUtil.map(ticks, numval => {
134	                const tick = {value: numval};
135	                return {
136	                    formattedLabel: labelFormatter(tick),
137	                    rawLabel: axis.scale.getLabel(tick),
138	                    tickValue: numval,
139	                    time: undefined as ScaleTick['time'] | NullUndefined,
140	                    break: undefined as VisualAxisBreak | NullUndefined,
141	                };
142	            }),
143	        };
144	    }
145	    // Only ordinal scale support tick interval
146	    return axis.type === 'category'
147	        ? makeCategoryLabels(axis, ctx)
148	        : makeRealNumberLabels(axis);
149	}
150	
151	/**
152	 * @param tickModel For example, can be axisTick, splitLine, splitArea.
153	 */
154	export function createAxisTicks(
155	    axis: Axis,
156	    tickModel: AxisBaseModel,
157	    opt?: Pick<ScaleGetTicksOpt, 'breakTicks' | 'pruneByBreak'>
158	): {
159	    ticks: number[],
160	    tickCategoryInterval?: number
161	} {
162	    const custom = axis.getTickModel().get('customValues');
163	    if (custom) {
164	        const extent = axis.scale.getExtent();
165	        const tickNumbers = tickValuesToNumbers(axis, custom);
166	        return {
167	            ticks: zrUtil.filter(tickNumbers, val => val >= extent[0] && val <= extent[1])
168	        };
169	    }
170	    // Only ordinal scale support tick interval
171	    return axis.type === 'category'
172	        ? makeCategoryTicks(axis, tickModel)
173	        : {ticks: zrUtil.map(axis.scale.getTicks(opt), tick => tick.value)};
174	}
175	
176	function makeCategoryLabels(axis: Axis, ctx: AxisLabelsComputingContext): ReturnType<typeof createAxisLabels> {
177	    const labelModel = axis.getLabelModel();
178	    const result = makeCategoryLabelsActually(axis, labelModel, ctx);
179	
180	    return (!labelModel.get('show') || axis.scale.isBlank())
181	        ? {labels: []}
182	        : result;
183	}
184	
185	function makeCategoryLabelsActually(
186	    axis: Axis,
187	    labelModel: Model<AxisBaseOption['axisLabel']>,
188	    ctx: AxisLabelsComputingContext
189	): {
190	    labels: AxisLabelInfoDetermined[]
191	    labelCategoryInterval: number
192	} {
193	    const labelsCache = ensureCategoryLabelCache(axis);
194	    const optionLabelInterval = getOptionCategoryInterval(labelModel);
195	    const isEstimate = ctx.kind === AxisTickLabelComputingKind.estimate;
196	
197	    // In AxisTickLabelComputingKind.estimate, the result likely varies during a single
198	    // pass of ec main process,due to the change of axisExtent, and will not be shared with
199	    // splitLine. Therefore no cache is used.
200	    if (!isEstimate) {
201	        // PENDING: check necessary?
202	        const result = axisCacheGet(labelsCache, optionLabelInterval);
203	        if (result) {
204	            return result;
205	        }
206	    }
207	
208	    let labels;
209	    let numericLabelInterval;
210	
211	    if (zrUtil.isFunction(optionLabelInterval)) {
212	        labels = makeLabelsByCustomizedCategoryInterval(axis, optionLabelInterval);
213	    }
214	    else {
215	        numericLabelInterval = optionLabelInterval === 'auto'
216	            ? makeAutoCategoryInterval(axis, ctx) : optionLabelInterval;
217	        labels = makeLabelsByNumericCategoryInterval(axis, numericLabelInterval);
218	    }
219	
220	    const result = {labels, labelCategoryInterval: numericLabelInterval};
221	    if (!isEstimate) {
222	        axisCacheSet(labelsCache, optionLabelInterval, result);
223	    }
224	    else {
225	        ctx.out.noPxChangeTryDetermine.push(function () {
226	            axisCacheSet(labelsCache, optionLabelInterval, result);
227	            return true;
228	        });
229	    }
230	    return result;
231	}
